// Example: pages/index.vue
<template>
  <div>
    <h1>Mission Control — Index</h1>
    <NuxtLink to="/about">About Sector</NuxtLink>
  </div>
</template>

// nuxt.config.ts
export default defineNuxtConfig({
  // Default: Universal (SSR) mode
  ssr: true,

  // SPA mode (no SSR):
  // ssr: false,

  // Static generation (pre-render all routes):
  // nitro: { prerender: { routes: ['/'] } }
});

// pages/mission/[id].vue
<template>
  <div>
    <h1>Mission ID: {{ missionId }}</h1>
    <p>{{ missionData?.title }}</p>
  </div>
</template>

<script setup>
const route = useRoute();
const missionId = route.params.id;

// Fetch data based on ID
const { data: missionData } = await useFetch(`/api/missions/${missionId}`);
</script>

// nuxt.config.ts
export default defineNuxtConfig({
  modules: [
    '@pinia/nuxt',
    '@nuxt/image',
    '@nuxtjs/tailwindcss'
  ],

  // Runtime config (public variables)
  runtimeConfig: {
    public: {
      apiBase: process.env.NUXT_API_BASE
    }
  },

  // Custom head tags
  app: {
    head: { title: 'Mission Control' }
  }
});

// server/api/missions.get.ts
export default defineEventHandler(async (event) => {
  // This code only runs on the server!
  const missions = await db.query('SELECT * FROM missions');
  return missions;
});

// server/api/missions/[id].get.ts
export default defineEventHandler(async (event) => {
  const id = getRouterParam(event, 'id');
  return await db.find('missions', id);
});
